function switchTeam(i,dest){if(!state.teams[i])return;if(dest)exploreReturn=null;activeTeam=i;partySlot=null;selected=team().selected||'grass';if(dest)tab=dest;render();window.scrollTo(0,0)}
function teamStatus(t){return t.explore?`${stg(t.explore.stageId).name} 探索中 / 残り ${duration(Math.max(0,t.explore.ends-now()))}`:t.party.length===4?'待機中':'待機中（編成 '+t.party.length+'/4）'}
